let result = seq.map();
result.orderId = order_id;
result.customerName = customer.first_name + ' ' + customer.last_name;
result.contactEmail = customer.email;
result.emailDomain = string.substring(customer.email, string.indexOf(customer.email, '@') + 1);
result.itemCount = count(items);
let subtotal = reduce(items, lambda(sum, item) -> sum + item.price * item.qty end, 0);
result.subtotal = math.round(subtotal * 100) / 100;
result.discount = math.round(subtotal * discount_rate * 100) / 100;
result.totalAmount = math.round(subtotal * (1 - discount_rate) * 100) / 100;
result.orderDate = string.substring(created_at, 0, 10);
result.isPremium = result.totalAmount > 50;
result.status = result.isPremium ? 'VIP' : 'NORMAL';
result.skuList = map(items, lambda(item) -> item.sku end);
return result;
